import events from './events.json' with {type:'json'};

// Opaque cursor: base64-encoded JSON describing the next start index.
// Stateless but not trivially guessable; malformed/out-of-range values are rejected.
function encodeCursor(index) {
  return Buffer.from(JSON.stringify({i: index}), 'utf8').toString('base64');
}

function decodeCursor(cursor) {
  let decoded;
  try {
    decoded = JSON.parse(Buffer.from(cursor, 'base64').toString('utf8'));
  } catch {
    throw new Error('Unknown cursor');
  }
  if (
    typeof decoded !== 'object' || decoded === null ||
    !Number.isInteger(decoded.i) ||
    decoded.i < 0 || decoded.i >= events.length
  ) {
    throw new Error('Unknown cursor');
  }
  return decoded.i;
}

export async function listTools() {
  return [
    {
      name: 'events_list',
      description: 'List events one page at a time in source order.',
      inputSchema: {
        type: 'object',
        properties: {
          cursor: { type: 'string', description: 'Opaque cursor returned from a previous page.' },
          page_size: { type: 'integer', minimum: 1, maximum: 3, description: 'Events per page (1-3, default 2).' }
        },
        required: [],
        additionalProperties: false
      }
    }
  ];
}

export async function callTool(name, args) {
  if (name !== 'events_list') {
    throw new Error(`Unknown tool: ${name}`);
  }

  if (typeof args !== 'object' || args === null || Array.isArray(args)) {
    throw new Error('Arguments must be an object');
  }

  // Reject extra/unknown fields.
  for (const key of Object.keys(args)) {
    if (key !== 'cursor' && key !== 'page_size') {
      throw new Error(`Unknown field: ${key}`);
    }
  }

  // Validate cursor.
  let start = 0;
  if (args.cursor !== undefined) {
    if (typeof args.cursor !== 'string') {
      throw new Error('cursor must be a string');
    }
    start = decodeCursor(args.cursor);
  }

  // Validate page_size (default 2, range 1-3, must be an integer).
  let pageSize = 2;
  if (args.page_size !== undefined) {
    if (
      typeof args.page_size !== 'number' ||
      !Number.isInteger(args.page_size) ||
      args.page_size < 1 ||
      args.page_size > 3
    ) {
      throw new Error('page_size must be an integer from 1 to 3');
    }
    pageSize = args.page_size;
  }

  const slice = events.slice(start, start + pageSize);
  const result = { events: slice };
  if (start + pageSize < events.length) {
    result.next_cursor = encodeCursor(start + pageSize);
  }

  return {
    content: [{ type: 'text', text: JSON.stringify(result) }]
  };
}

