import { callTool, listTools } from "./server.mjs";

const eq = (a, b) => JSON.stringify(a) === JSON.stringify(b);

// 1. listTools: schema has additionalProperties:false
const tools = await listTools();
console.assert(tools.length === 1 && tools[0].name === "events_list", "listTools name");
console.assert(tools[0].inputSchema.additionalProperties === false, "additionalProperties:false");
console.assert(eq(tools[0].inputSchema.required, []), "required empty");
console.assert(tools[0].inputSchema.properties.page_size.minimum === 1, "page_size min");
console.assert(tools[0].inputSchema.properties.page_size.maximum === 3, "page_size max");

// 2. first page default (page_size=2): e1,e2 + next_cursor
let r = await callTool("events_list", {});
let body = JSON.parse(r.content[0].text);
console.assert(eq(body.events, [{id:"e1",name:"Start"},{id:"e2",name:"Build"}]), "page1 events");
console.assert(typeof body.next_cursor === "string", "page1 next cursor");
console.assert(r.content[0].type === "text", "content type text");

// 3. second page via cursor: e3,e4 + no next_cursor
r = await callTool("events_list", { cursor: body.next_cursor });
body = JSON.parse(r.content[0].text);
console.assert(eq(body.events, [{id:"e3",name:"Test"},{id:"e4",name:"Ship"}]), "page2 events");
console.assert(body.next_cursor === undefined, "page2 no next cursor");

// 4. page_size=1 -> 4 pages, each single event
let cur;
const collected = [];
for (let i = 0; i < 4; i++) {
  const args = cur ? { cursor: cur, page_size: 1 } : { page_size: 1 };
  r = await callTool("events_list", args);
  body = JSON.parse(r.content[0].text);
  collected.push(...body.events);
  cur = body.next_cursor;
}
console.assert(eq(collected, [
  {id:"e1",name:"Start"},{id:"e2",name:"Build"},{id:"e3",name:"Test"},{id:"e4",name:"Ship"}
]), "page_size=1 full traversal");
console.assert(cur === undefined, "page_size=1 ends with no cursor");

// 5. page_size=3 -> page1 e1-e3 with cursor, page2 e4 no cursor
r = await callTool("events_list", { page_size: 3 });
body = JSON.parse(r.content[0].text);
console.assert(eq(body.events, [{id:"e1",name:"Start"},{id:"e2",name:"Build"},{id:"e3",name:"Test"}]), "ps3 page1");
r = await callTool("events_list", { cursor: body.next_cursor });
body = JSON.parse(r.content[0].text);
console.assert(eq(body.events, [{id:"e4",name:"Ship"}]), "ps3 page2");
console.assert(body.next_cursor === undefined, "ps3 page2 no cursor");

// 6. unknown cursor rejected
for (const bad of ["garbage", "", "not-base64!!!", "eyJpIjoxMDB9"]) {
  try { await callTool("events_list", { cursor: bad }); throw new Error("should have thrown for " + bad); }
  catch (e) { console.assert(/Unknown cursor/.test(e.message), "reject " + bad); }
}

// 7. invalid page_size
for (const bad of [0, 4, 2.5, "2", true, null]) {
  try { await callTool("events_list", { page_size: bad }); throw new Error("should have thrown for ps=" + JSON.stringify(bad)); }
  catch (e) { console.assert(/page_size/.test(e.message), "reject ps=" + JSON.stringify(bad)); }
}

// 8. invalid cursor type
try { await callTool("events_list", { cursor: 123 }); throw new Error("no throw"); }
catch (e) { console.assert(/cursor must be a string/.test(e.message), "cursor type"); }

// 9. extra field rejected
try { await callTool("events_list", { extra: 1 }); throw new Error("no throw"); }
catch (e) { console.assert(/Unknown field/.test(e.message), "extra field"); }

// 10. unknown tool rejected
try { await callTool("nope", {}); throw new Error("no throw"); }
catch (e) { console.assert(/Unknown tool/.test(e.message), "unknown tool"); }

// 11. cursor past end rejected (should not be returned, but tampering should fail)
// encode a cursor beyond range
const tampered = Buffer.from(JSON.stringify({i:99})).toString("base64");
try { await callTool("events_list", { cursor: tampered }); throw new Error("no throw"); }
catch (e) { console.assert(/Unknown cursor/.test(e.message), "tampered cursor oob"); }

// 12. final cursor (pointing to exact end) should not be returned by server; verify last page returns no cursor when exactly consumed
r = await callTool("events_list", { page_size: 2 }); // e1,e2 cursor->2
body = JSON.parse(r.content[0].text);
r = await callTool("events_list", { cursor: body.next_cursor }); // e3,e4, no cursor
body = JSON.parse(r.content[0].text);
console.assert(body.next_cursor === undefined, "exact end no cursor");

// 13. replaying a valid cursor is allowed (idempotent)
r = await callTool("events_list", { page_size: 2 });
const c = JSON.parse(r.content[0].text).next_cursor;
const a = await callTool("events_list", { cursor: c });
const b = await callTool("events_list", { cursor: c });
console.assert(eq(JSON.parse(a.content[0].text), JSON.parse(b.content[0].text)), "cursor replay idempotent");

console.log("ALL CHECKS PASSED");
'"}

